// utils.js
export function formatarData(data) {
  return new Intl.DateTimeFormat('pt-PT').format(data);
}

export function gerarId() {
  return crypto.randomUUID();
}

export function registar(mensagem) {
  console.log(`[log] ${mensagem}`);
}

// main.js
import { formatarData, gerarId } from './utils.js';

console.log(formatarData(new Date()));
console.log(gerarId());

export default {
  presets: [
    ['@babel/preset-env', { targets: '> 0.5%, not dead' }],
  ],
};

import js from '@eslint/js';

export default [
  js.configs.recommended,
  {
    rules: {
      'no-var': 'error',
      eqeqeq: 'error',
      'no-unused-vars': 'warn',
    },
  },
];

const scripts = {
  lint: 'eslint .',
  format: 'prettier --write .',
};

console.log(scripts);

import { build } from 'esbuild';

async function gerarBuild() {
  try {
    await build({
      entryPoints: ['src/index.js'],
      outfile: 'dist/bundle.js',
      bundle: true,
      minify: true,
      target: ['es2018'],
    });
    console.log('Build concluído com sucesso.');
  } catch (erro) {
    console.error('Falha no build:', erro);
    process.exit(1);
  }
}

gerarBuild();
